const detailField=(detail,locale,key)=>detail?.[key]?.[locale==='tr'?0:locale==='en'?1:locale==='el'?2:3]||'';

const signGlyphs=['♈','♉','♊','♋','♌','♍','♎','♏','♐','♑','♒','♓'];
const planetGlyphs={gunes:'☉',ay:'☽',merkur:'☿',venus:'♀',mars:'♂',jupiter:'♃',saturn:'♄',uranus:'♅',neptun:'♆',pluton:'♇'};
const aspectGlyphs={kavusum:'☌',karsit:'☍',kare:'□',ucgen:'△',sekstil:'✶',quincunx:'⚻'};
const symbolFor=url=>{const slug=url.split('/').filter(Boolean).at(-1);if(url.startsWith('/burclar/'))return signGlyphs[signs.findIndex(x=>x[0]===slug)]||'✦';if(url.startsWith('/evler/'))return slug;if(url.startsWith('/gezegenler/'))return planetGlyphs[slug]||'✦';if(url.startsWith('/acilar/'))return aspectGlyphs[slug]||'◇';return url==='/transitler'?'↗':'℞'};
const L=(row,locale,i)=>locale==='tr'?row[i]:locale==='en'?row[i+1]:locale==='es'?esField(row,i):row[i+2];
const path=(p,l)=>l==='tr'?p:`/${l}${p}`;
const shell=(locale,title,description,body,canonical,schemas=[])=>`<!doctype html><html lang="${locale==='tr'?'tr-TR':locale}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} — Mythborn</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${SITE}${path(canonical,locale)}"><link rel="alternate" hreflang="tr" href="${SITE}${path(canonical,'tr')}"><link rel="alternate" hreflang="en" href="${SITE}${path(canonical,'en')}"><link rel="alternate" hreflang="el" href="${SITE}${path(canonical,'el')}"><link rel="alternate" hreflang="es" href="${SITE}${path(canonical,'es')}"><link rel="alternate" hreflang="x-default" href="${SITE}${path(canonical,'tr')}"><link rel="stylesheet" href="/app.css"><link rel="stylesheet" href="/oracle.css"><link rel="stylesheet" href="/final.css">${schemas.map(s=>`<script type="application/ld+json">${JSON.stringify(s)}</script>`).join('')}</head><body><div class="shell"><header class="topbar"><a class="brand" href="${path('/',locale)}"><img src="/images/mythborn-emblem.png" alt=""><span>MYTHBORN</span></a><nav class="nav"><a href="${path('/astroloji',locale)}">${locale==='tr'?'Astroloji':locale==='en'?'Astrology':locale==='es'?'Astrología':'Αστρολογία'}</a><a href="${path('/astroloji-kutuphanesi',locale)}">${ui[locale].home}</a><a href="${path('/advanced-astrology',locale)}">${locale==='tr'?'Gelişmiş':locale==='tr'?'Gelişmiş':locale==='en'?'Advanced':locale==='es'?'Avanzada':'Προχωρημένα'}</a><a href="${path('/blog',locale)}">Blog</a></nav></header><main>${body}</main><footer class="footer"><span>© 2026 Mythborn</span><span>${ui[locale].note}</span></footer></div><style>.library-hero{padding:70px 0 32px}.library-hero h1,.library-page h1{font-family:Georgia,serif;font-size:clamp(44px,7vw,78px);line-height:.98;font-weight:400}.library-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;padding-bottom:70px}.library-card{padding:22px;border:1px solid rgba(255,255,255,.12);border-radius:20px;background:rgba(255,255,255,.03)}.library-card h2{font:400 clamp(25px,3vw,36px)/1.05 Georgia,serif}.library-card p,.library-page p{color:#aaa2b0;line-height:1.75}.library-page{width:min(880px,100%);margin:auto;padding:62px 0}.library-page section{padding:28px 0;border-top:1px solid rgba(255,255,255,.11)}.library-page h2{font:400 clamp(28px,4vw,44px)/1.05 Georgia,serif}.library-meta{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.library-meta span{padding:8px 12px;border:1px solid rgba(255,255,255,.12);border-radius:999px;color:#e8c883}.library-groups{display:grid;gap:28px}@media(max-width:850px){.library-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.library-grid{grid-template-columns:1fr}.library-hero,.library-page{padding-top:42px}}</style><script src="/final.js" defer></script><script src="/menu.js" defer></script></body></html>`;
const schemas=(locale,title,description,url,faq)=>[{'@context':'https://schema.org','@type':'Article',headline:title,description,inLanguage:locale==='tr'?'tr-TR':locale,url:`${SITE}${path(url,locale)}`,publisher:{'@type':'Organization',name:'Mythborn'}},{'@context':'https://schema.org','@type':'FAQPage',mainEntity:faq.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))},{'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Mythborn',item:SITE},{'@type':'ListItem',position:2,name:ui[locale].home,item:`${SITE}${path('/astroloji-kutuphanesi',locale)}`},{'@type':'ListItem',position:3,name:title,item:`${SITE}${path(url,locale)}`}]}];
const genericFaq=(locale,name)=>locale==='tr'?[[`${name} tek başına yeterli mi?`,`Hayır. Yerleşim; burç, ev, açı ve haritanın bütünüyle birlikte okunmalıdır.`],[`${name} kesin kader gösterir mi?`,`Hayır. Astrolojik semboller olasılık, eğilim ve farkındalık dili sunar.`]]:locale==='en'?[[`Is ${name} enough on its own?`,`No. Read it with sign, house, aspects and the chart as a whole.`],[`Does ${name} describe fixed fate?`,`No. Astrological symbols describe tendencies and reflection themes, not certainty.`]]:locale==='es'?[[`¿Basta ${name} por sí solo?`,`No. Debe leerse junto con el signo, la casa, los aspectos y la carta completa.`],[`¿${name} describe un destino fijo?`,`No. Los símbolos astrológicos describen tendencias y temas de reflexión, no certezas.`]]:[[`Αρκεί μόνο το ${name};`,`Όχι. Χρειάζεται να διαβαστεί μαζί με ζώδιο, οίκο, όψεις και ολόκληρο τον χάρτη.`],[`Δείχνει το ${name} σταθερή μοίρα;`,`Όχι. Τα σύμβολα δείχνουν τάσεις και θέματα στοχασμού, όχι βεβαιότητα.`]];
const signFaq=(locale,item,title)=>{
 const d=signDetails[item[0]],dates=detailField(d,locale,'dates'),ruler=detailField(d,locale,'ruler'),love=detailField(d,locale,'love'),career=detailField(d,locale,'career');
 if(locale==='tr')return[
  [title+' burcu hangi tarihler arasında?','Yaklaşık '+dates+'. Sınır günlerinde Güneş’in burç değişim anı doğum yılı ve saate göre farklılaşabilir.'],
  [title+' burcunun yönetici gezegeni nedir?',ruler+'. Yönetici gezegen burcun işleyişini anlamak için sembolik bir anahtar sunar.'],
  [title+' burcu aşkta nasıldır?','İlişkilerde '+love+' temaları belirgindir; Venüs, Ay, Mars ve 7. ev kişisel ilişki tarzını ayrıntılandırır.'],
  [title+' burcu hangi işlerde güçlü olabilir?','Kariyerde '+career+' öne çıkabilir. Meslek seçimi tek başına Güneş burcuna göre yapılmamalıdır.'],
  [title+' yükseleni ile '+title+' Güneş burcu aynı şey mi?','Hayır. Güneş kimlik ve bilinçli yönü; yükselen dış dünyaya yaklaşım, ilk izlenim ve ev sisteminin başlangıcını anlatır.'],
  [title+' burcu tek başına kişiliği açıklar mı?','Hayır. Ay, yükselen, Merkür, Venüs, Mars, evler ve açılarla birlikte bütün harita değerlendirilmelidir.']
 ];
 if(locale==='en')return[
  ['What are the approximate '+title+' dates?','Approximately '+dates+'. On cusp dates, the exact Sun ingress can vary by year and birth time.'],
  ['What planet rules '+title+'?',ruler+'. The ruling planet is a symbolic key to how the sign operates.'],
  ['What is '+title+' like in relationships?','Themes include '+love+'; Venus, Moon, Mars and the 7th house add personal context.'],
  ['What career strengths are associated with '+title+'?',career+' can stand out, but career choice should not be reduced to the Sun sign alone.'],
  ['Is '+title+' rising the same as a '+title+' Sun?','No. The Sun describes identity and conscious direction; the Ascendant describes approach, presentation and the starting point of the house system.'],
  ['Does '+title+' alone explain personality?','No. Read the Moon, Ascendant, Mercury, Venus, Mars, houses and aspects with the chart as a whole.']
 ];
 if(locale==='es')return[
  ['¿Cuáles son las fechas aproximadas de '+title+'?','Aproximadamente '+dates+'. En fechas límite, el ingreso exacto del Sol puede variar según el año y la hora.'],
  ['¿Qué planeta rige '+title+'?',ruler+'. El regente es una clave simbólica para comprender el signo.'],
  ['¿Cómo es '+title+' en el amor?','Destacan '+love+'; Venus, Luna, Marte y la casa 7 añaden contexto personal.'],
  ['¿Qué fortalezas profesionales se asocian con '+title+'?',career+' puede destacar, pero una profesión no debe elegirse solo por el signo solar.'],
  ['¿Ascendente '+title+' es igual a Sol en '+title+'?','No. El Sol describe identidad y dirección consciente; el Ascendente describe enfoque, presentación e inicio de las casas.'],
  ['¿'+title+' explica toda la personalidad?','No. Conviene leer Luna, Ascendente, Mercurio, Venus, Marte, casas y aspectos en conjunto.']
 ];
 return[
  ['Ποιες είναι περίπου οι ημερομηνίες του '+title+';','Περίπου '+dates+'. Στις οριακές ημερομηνίες η ακριβής είσοδος του Ήλιου αλλάζει ανά έτος και ώρα γέννησης.'],
  ['Ποιος πλανήτης κυβερνά το '+title+';',ruler+'. Ο κυβερνήτης είναι συμβολικό κλειδί για τον τρόπο λειτουργίας του ζωδίου.'],
  ['Πώς είναι το '+title+' στις σχέσεις;','Κύρια θέματα: '+love+'. Αφροδίτη, Σελήνη, Άρης και 7ος οίκος προσθέτουν προσωπικό πλαίσιο.'],
  ['Ποια επαγγελματικά δυνατά σημεία συνδέονται με το '+title+';',career+' μπορεί να ξεχωρίζει, αλλά η καριέρα δεν βασίζεται μόνο στο ζώδιο του Ήλιου.'],
  ['Είναι ίδιος ο Ωροσκόπος '+title+' με Ήλιο στο '+title+';','Όχι. Ο Ήλιος αφορά ταυτότητα και συνειδητή κατεύθυνση, ενώ ο Ωροσκόπος προσέγγιση και πρώτη εντύπωση.'],
  ['Αρκεί το '+title+' για να εξηγήσει την προσωπικότητα;','Όχι. Χρειάζονται Σελήνη, Ωροσκόπος, Ερμής, Αφροδίτη, Άρης, οίκοι και όψεις μαζί.']
 ];
};
