 const h=locale==='tr'?{profile:'Hızlı profil',ruler:'Yönetici',love:'Aşk ve ilişkiler',career:'Kariyer ve çalışma biçimi',money:'Para ve kaynak yönetimi',communication:'İletişim tarzı',placements:'Güneş, Ay ve Yükselen farkı',chart:'Doğum haritasında nasıl okunur?',deeper:'Daha derine in',calc:'Doğum haritanı hesapla',year:'2027 yıllık rehberi',syn:'Sinastri hesapla'}:locale==='en'?{profile:'Quick profile',ruler:'Ruler',love:'Love and relationships',career:'Career and work style',money:'Money and resources',communication:'Communication style',placements:'Sun, Moon and Rising',chart:'How to read it in a birth chart',deeper:'Go deeper',calc:'Calculate your birth chart',year:'2027 guide',syn:'Calculate synastry'}:locale==='es'?{profile:'Perfil rápido',ruler:'Regente',love:'Amor y relaciones',career:'Carrera y estilo de trabajo',money:'Dinero y recursos',communication:'Estilo de comunicación',placements:'Sol, Luna y Ascendente',chart:'Cómo leerlo en la carta natal',deeper:'Profundiza',calc:'Calcula tu carta natal',year:'Guía 2027',syn:'Calcula sinastría'}:{profile:'Γρήγορο προφίλ',ruler:'Κυβερνήτης',love:'Αγάπη και σχέσεις',career:'Καριέρα και τρόπος εργασίας',money:'Χρήματα και πόροι',communication:'Τρόπος επικοινωνίας',placements:'Ήλιος, Σελήνη και Ωροσκόπος',chart:'Πώς διαβάζεται στον γενέθλιο χάρτη',deeper:'Πήγαινε βαθύτερα',calc:'Υπολόγισε τον γενέθλιο χάρτη σου',year:'Οδηγός 2027',syn:'Υπολόγισε συναστρία'};
