export const libraryRoutes=['/astroloji-kutuphanesi',...signs.map(x=>`/burclar/${x[0]}`),...houses.map(x=>`/evler/${x[0]}`),...planets.map(x=>`/gezegenler/${x[0]}`),...aspects.map(x=>`/acilar/${x[0]}`),'/transitler','/retro-hareketler'];
